const https = require('https');

function getBizInfo(bizNo) {
  return new Promise((resolve) => {
    const cleanNo = bizNo.replace(/[^0-9]/g, '');
    https.get('https://bizno.net/article/' + cleanNo, { headers: { 'User-Agent': 'Mozilla/5.0' } }, (res) => {
      let data = '';
      res.on('data', chunk => data += chunk);
      res.on('end', () => {
        let status = '-';
        let revenue = '-';
        let type = '-';
        const mStatus = data.match(/사업자 현재 상태\s*<\/th>\s*<td[^>]*>([\s\S]*?)<\/td>/);
        if (mStatus) status = mStatus[1].replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim();
        const mRev = data.match(/연매출액\s*<\/th>\s*<td[^>]*>([\s\S]*?)<\/td>/);
        if (mRev) revenue = mRev[1].replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim();
        const mType = data.match(/법인형태\s*<\/th>\s*<td[^>]*>([\s\S]*?)<\/td>/);
        if (mType) type = mType[1].replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim();
        resolve({ bizNo, status, revenue, type });
      });
    }).on('error', () => resolve({ bizNo, status: 'error', revenue: '-', type: '-' }));
  });
}

